package kronex.fun.display.screens.clickgui.components.implement.window.implement.settings.color;
import net.minecraft.client.gui.DrawContext; import kronex.fun.features.module.setting.implement.ColorSetting; import kronex.fun.other.utils.display.shape.ShapeProperties; import kronex.fun.other.utils.display.color.ColorAssist; import kronex.fun.other.utils.math.MathUtil; import kronex.fun.display.screens.clickgui.components.AbstractComponent; import kronex.fun.display.screens.clickgui.components.implement.window.AbstractWindow; import kronex.fun.display.screens.clickgui.components.implement.window.implement.settings.color.component.*; import java.util.*;
public class ColorWindow extends AbstractWindow { private final List<AbstractComponent> components=new ArrayList<>(); private final HueComponent hueComponent; private final SaturationComponent saturationComponent; private final AlphaComponent alphaComponent; private final ColorEditorComponent colorEditorComponent; private final ColorPresetComponent colorPresetComponent;
 public ColorWindow(ColorSetting setting){components.addAll(Arrays.asList(hueComponent=new HueComponent(setting),saturationComponent=new SaturationComponent(setting),alphaComponent=new AlphaComponent(setting),colorEditorComponent=new ColorEditorComponent(setting),colorPresetComponent=new ColorPresetComponent(setting)));}
 public void drawWindow(DrawContext context,int mouseX,int mouseY,float delta){rectangle.render(ShapeProperties.create(context.getMatrices(),x,y,width,height).round(6).thickness(2).softness(1).outlineColor(ColorAssist.getOutline()).color(ColorAssist.getMainGuiColor()).build());alphaComponent.position(x,y);hueComponent.position(x,y);saturationComponent.position(x,y);colorEditorComponent.position(x,y);height=((ColorPresetComponent)colorPresetComponent.position(x,y)).getWindowHeight()+10;components.forEach(c->c.render(context,mouseX,mouseY,delta));}
 public boolean mouseClicked(double mouseX,double mouseY,int button){draggable(MathUtil.isHovered(mouseX,mouseY,x,y,width,17));components.forEach(c->c.mouseClicked(mouseX,mouseY,button));return super.mouseClicked(mouseX,mouseY,button);}
 public boolean mouseScrolled(double mouseX,double mouseY,double amount){components.forEach(c->c.mouseScrolled(mouseX,mouseY,amount));return super.mouseScrolled(mouseX,mouseY,amount);}
 public boolean mouseReleased(double mouseX,double mouseY,int button){components.forEach(c->c.mouseReleased(mouseX,mouseY,button));return super.mouseReleased(mouseX,mouseY,button);}
}